24	export function mediaAspectRatioFor(item: LibraryItem): number {
25	  if (
26	    item.mediaAspectRatio &&
27	    Number.isFinite(item.mediaAspectRatio) &&
28	    item.mediaAspectRatio > 0
29	  ) {
30	    return item.mediaAspectRatio;
31	  }
32	  if (item.mediaWidth && item.mediaHeight && item.mediaWidth > 0 && item.mediaHeight > 0) {
33	    return item.mediaWidth / item.mediaHeight;
34	  }
35	
36	  // Keep native X posts compact enough to read as a card while leaving the
37	  // full-height version available in the detail view.
38	  if (item.social?.provider === "x") return 1.6;
39	
40	  switch (item.kind) {
41	    case "Video":
42	      return 16 / 9;
43	    case "Article":
44	      return 16 / 10;
45	    case "Image":
46	      return 4 / 3;
47	    case "Post":
48	      return 1.45;
49	    case "PDF":
50	      return 4 / 3;
51	    case "Quote":
52	      return 1.4;
53	    default:
54	      return 1.45;
55	  }
56	}
