168	export function formatDuration(totalSeconds: number): string {
169	  const seconds = Math.floor(totalSeconds);
170	  const hours = Math.floor(seconds / 3600);
171	  const minutes = Math.floor((seconds % 3600) / 60);
172	  const rest = String(seconds % 60).padStart(2, "0");
173	  return hours > 0 ? `${hours}:${String(minutes).padStart(2, "0")}:${rest}` : `${minutes}:${rest}`;
174	}
