283	type XWidgets = {
284	  widgets?: {
285	    load: (element?: HTMLElement) => void;
286	  };
287	};
288	
289	declare global {
290	  interface Window {
291	    twttr?: XWidgets;
292	  }
293	}
294	
295	let xWidgetsPromise: Promise<void> | null = null;
296	const X_WIDGETS_SRC = "https://platform.twitter.com/widgets.js";
297	
298	function loadXWidgets() {
299	  if (typeof window === "undefined" || window.twttr?.widgets) return Promise.resolve();
300	  if (xWidgetsPromise) return xWidgetsPromise;
301	
302	  xWidgetsPromise = new Promise<void>((resolve, reject) => {
303	    const existing = document.querySelector<HTMLScriptElement>("#twitter-wjs");
304	    const script = existing ?? document.createElement("script");
305	    let pollId: number | undefined;
306	    let timeoutId: number | undefined;
307	    let settled = false;
308	
309	    const finish = (error?: Error) => {
310	      if (settled) return;
311	      settled = true;
312	      if (pollId !== undefined) window.clearInterval(pollId);
313	      if (timeoutId !== undefined) window.clearTimeout(timeoutId);
314	      if (error) reject(error);
315	      else resolve();
316	    };
317	
318	    const checkReady = () => {
319	      if (window.twttr?.widgets) finish();
320	    };
321	
322	    const handleLoad = () => {
323	      checkReady();
324	      window.setTimeout(checkReady, 0);
325	    };
326	    const handleError = () => finish(new Error("X widgets could not be loaded."));
327	
328	    script.addEventListener("load", handleLoad, { once: true });
329	    script.addEventListener("error", handleError, { once: true });
330	
331	    if (!existing) {
332	      script.id = "twitter-wjs";
333	      script.src = X_WIDGETS_SRC;
334	      script.async = true;
335	      script.charset = "utf-8";
336	      document.head.appendChild(script);
337	    }
338	
339	    checkReady();
340	    pollId = window.setInterval(checkReady, 100);
341	    timeoutId = window.setTimeout(() => finish(new Error("X widgets timed out.")), 15000);
342	  });
343	
344	  return xWidgetsPromise;
345	}
346	
347	function waitForXWidget(root: HTMLElement, timeoutMs = 8000): Promise<boolean> {
348	  return new Promise((resolve) => {
349	    let settled = false;
350	    let observer: MutationObserver | null = null;
351	    let timeoutId: number | undefined;
352	
353	    const finish = (loaded: boolean) => {
354	      if (settled) return;
355	      settled = true;
356	      observer?.disconnect();
357	      if (timeoutId !== undefined) window.clearTimeout(timeoutId);
358	      resolve(loaded);
359	    };
360	
361	    const watchWidget = () => {
362	      const iframe = root.querySelector<HTMLIFrameElement>("iframe");
363	      if (!iframe) return;
364	
365	      // X replaces the blockquote with its official cross-origin iframe. The
366	      // iframe load event is not a reliable readiness signal here: cached
367	      // frames can finish before a listener is attached, and some browsers do
368	      // not surface a second load event for an already-created frame. Seeing
369	      // the official iframe is the stable signal that widgets.js transformed
370	      // this embed. Do not wait for requestAnimationFrame here: the preview
371	      // can be backgrounded, and browsers throttle animation frames in that
372	      // state even though the cross-origin iframe has already loaded.
373	      finish(true);
374	    };
375	
376	    observer = new MutationObserver(watchWidget);
377	    observer.observe(root, { childList: true, subtree: true });
378	    watchWidget();
379	    timeoutId = window.setTimeout(() => finish(false), timeoutMs);
380	  });
381	}
