1	import sharp from "sharp";
2	
3	const maxImageDimension = 20_000;
4	const maxImageAllocation = 256 * 1024 * 1024;
5	const maxImagePixels = Math.floor(maxImageAllocation / 8);
6	const thumbnailEdge = 512;
7	
8	export function validateImageDimensions(width, height) {
9	  if (!width || !height) throw new Error("image processing error: unable to decode image");
10	  if (
11	    width > maxImageDimension ||
12	    height > maxImageDimension ||
13	    width * height * 8 > maxImageAllocation
14	  ) {
15	    throw new Error("image processing error: image dimensions exceed safe limits");
16	  }
17	}
18	
19	function validateIconImage(bytes) {
20	  const count = bytes.readUInt16LE(4);
21	  const directoryEnd = 6 + count * 16;
22	  if (count < 1 || directoryEnd > bytes.length) {
23	    throw new Error("invalid ICO image directory");
24	  }
25	
26	  for (let index = 0; index < count; index += 1) {
27	    const entry = 6 + index * 16;
28	    validateImageDimensions(bytes[entry] || 256, bytes[entry + 1] || 256);
29	    const size = bytes.readUInt32LE(entry + 8);
30	    const offset = bytes.readUInt32LE(entry + 12);
31	    if (offset < directoryEnd || offset + size > bytes.length || size < 12) {
32	      throw new Error("invalid ICO image data");
33	    }
34	
35	    const image = bytes.subarray(offset, offset + size);
36	    const isPng = image.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]));
37	    if (isPng) {
38	      if (image.length < 24) throw new Error("invalid ICO PNG data");
39	      validateImageDimensions(image.readUInt32BE(16), image.readUInt32BE(20));
40	      continue;
41	    }
42	
43	    const headerSize = image.readUInt32LE(0);
44	    if (headerSize >= 40 && headerSize <= size) {
45	      validateImageDimensions(Math.abs(image.readInt32LE(4)), Math.abs(image.readInt32LE(8)));
46	      continue;
47	    }
48	    if (headerSize === 12) {
49	      validateImageDimensions(image.readUInt16LE(4), image.readUInt16LE(6));
50	      continue;
51	    }
52	    throw new Error("unsupported ICO image data");
53	  }
54	}
55	
56	export async function sharpImageInput(bytes) {
57	  try {
58	    await sharp(bytes, { limitInputPixels: maxImagePixels }).metadata();
59	    return bytes;
60	  } catch (error) {
61	    const isBitmap = bytes.subarray(0, 2).toString("ascii") === "BM";
62	    const isIcon = bytes.length >= 6 && bytes.readUInt16LE(0) === 0 && bytes.readUInt16LE(2) === 1;
63	    if (!isBitmap && !isIcon) throw error;
64	    if (isIcon) validateIconImage(bytes);
65	    if (isBitmap && bytes.length >= 26) {
66	      const coreHeader = bytes.readUInt32LE(14) === 12;
67	      const width = coreHeader ? bytes.readUInt16LE(18) : bytes.readInt32LE(18);
68	      const height = coreHeader ? bytes.readUInt16LE(20) : bytes.readInt32LE(22);
69	      validateImageDimensions(Math.abs(width), Math.abs(height));
70	    }
71	    const [{ CanvasElement }, { default: loadImage }] = await Promise.all([
72	      import("@napi-rs/canvas/js-binding.js"),
73	      import("@napi-rs/canvas/load-image.js"),
74	    ]);
75	    const image = await loadImage(bytes);
76	    validateImageDimensions(image.width, image.height);
77	    const canvas = new CanvasElement(image.width, image.height);
78	    canvas.getContext("2d").drawImage(image, 0, 0);
79	    return canvas.encode("png");
80	  }
81	}
