156	export function formatFileSize(bytes: number): string {
157	  if (bytes < 1024) return `${bytes} B`;
158	  const units = ["KB", "MB", "GB", "TB"];
159	  let value = bytes / 1024;
160	  let unit = 0;
161	  while (value >= 1024 && unit < units.length - 1) {
162	    value /= 1024;
163	    unit += 1;
164	  }
165	  return `${value < 10 ? value.toFixed(1) : Math.round(value)} ${units[unit]}`;
166	}
