295	let xWidgetsPromise: Promise<void> | null = null;
296	const X_WIDGETS_SRC = "https://platform.twitter.com/widgets.js";
297	
298	function loadXWidgets() {
299	  if (typeof window === "undefined" || window.twttr?.widgets) return Promise.resolve();
300	  if (xWidgetsPromise) return xWidgetsPromise;
301	
302	  xWidgetsPromise = new Promise<void>((resolve, reject) => {
303	    const existing = document.querySelector<HTMLScriptElement>("#twitter-wjs");
304	    const script = existing ?? document.createElement("script");
305	    let pollId: number | undefined;
306	    let timeoutId: number | undefined;
307	    let settled = false;
308	
309	    const finish = (error?: Error) => {
310	      if (settled) return;
311	      settled = true;
312	      if (pollId !== undefined) window.clearInterval(pollId);
313	      if (timeoutId !== undefined) window.clearTimeout(timeoutId);
314	      if (error) reject(error);
315	      else resolve();
316	    };
317	
318	    const checkReady = () => {
319	      if (window.twttr?.widgets) finish();
320	    };
321	
322	    const handleLoad = () => {
323	      checkReady();
324	      window.setTimeout(checkReady, 0);
325	    };
326	    const handleError = () => finish(new Error("X widgets could not be loaded."));
327	
328	    script.addEventListener("load", handleLoad, { once: true });
329	    script.addEventListener("error", handleError, { once: true });
330	
331	    if (!existing) {
332	      script.id = "twitter-wjs";
333	      script.src = X_WIDGETS_SRC;
334	      script.async = true;
335	      script.charset = "utf-8";
336	      document.head.appendChild(script);
337	    }
338	
339	    checkReady();
340	    pollId = window.setInterval(checkReady, 100);
341	    timeoutId = window.setTimeout(() => finish(new Error("X widgets timed out.")), 15000);
342	  });
343	
344	  return xWidgetsPromise;
345	}
