383	export function XPostEmbed({ social, fallback }: { social: XPostMetadata; fallback: ReactNode }) {
384	  const nativeRef = useRef<HTMLDivElement>(null);
385	  const [shouldLoad, setShouldLoad] = useState(false);
386	  const [embedHtml, setEmbedHtml] = useState<string | undefined>(social.embedHtml);
387	  const [status, setStatus] = useState<"idle" | "loading" | "ready" | "failed">("idle");
388	
389	  useEffect(() => {
390	    setEmbedHtml(social.embedHtml);
391	    setStatus("idle");
392	  }, [social.embedHtml]);
393	
394	  useEffect(() => {
395	    if (!shouldLoad) return;
396	    let cancelled = false;
397	    setStatus("loading");
398	
399	    if (social.embedHtml) {
400	      setEmbedHtml(social.embedHtml);
401	      return () => {
402	        cancelled = true;
403	      };
404	    }
405	
406	    fetch(xPostOEmbedUrl(social.postUrl), { headers: { Accept: "application/json" } })
407	      .then((response) => {
408	        if (!response.ok) throw new Error(`X oEmbed returned HTTP ${response.status}.`);
409	        return response.json() as Promise<unknown>;
410	      })
411	      .then((payload) => {
412	        if (cancelled) return;
413	        const normalized = normalizeXPostOEmbed(
414	          social.postUrl,
415	          payload as Parameters<typeof normalizeXPostOEmbed>[1],
416	        );
417	        if (!normalized?.embedHtml) throw new Error("X did not return embed markup.");
418	        setEmbedHtml(normalized.embedHtml);
419	      })
420	      .catch(() => {
421	        if (!cancelled) setStatus("failed");
422	      });
423	
424	    return () => {
425	      cancelled = true;
426	    };
427	  }, [shouldLoad, social.embedHtml, social.postUrl]);
428	
429	  useEffect(() => {
430	    if (!shouldLoad) return;
431	    const root = nativeRef.current;
432	    if (!root || !embedHtml) return;
433	
434	    root.innerHTML = embedHtml;
435	    const updateEmbedWidth = () => {
436	      const width = Math.min(550, Math.max(280, Math.floor(root.getBoundingClientRect().width)));
437	      const iframe = root.querySelector<HTMLIFrameElement>("iframe");
438	
439	      if (iframe) {
440	        // The iframe itself is width: 100%; changing its URL after X has
441	        // rendered causes the widget to reload and can create a resize loop.
442	        // Its document receives the new viewport width through the iframe box.
443	        return;
444	      }
445	
446	      root
447	        .querySelector<HTMLElement>("blockquote.twitter-tweet")
448	        ?.setAttribute("data-width", String(width));
449	    };
450	
451	    updateEmbedWidth();
452	    const resizeObserver =
453	      typeof ResizeObserver === "undefined" ? null : new ResizeObserver(updateEmbedWidth);
454	    resizeObserver?.observe(root);
455	    window.addEventListener("resize", updateEmbedWidth);
456	    let cancelled = false;
457	    loadXWidgets()
458	      .then(async () => {
459	        if (cancelled) return;
460	        const widgetLoad = waitForXWidget(root);
461	        window.twttr?.widgets?.load(root);
462	        const loaded = await widgetLoad;
463	        if (!cancelled) setStatus(loaded ? "ready" : "failed");
464	      })
465	      .catch(() => {
466	        if (!cancelled) setStatus("failed");
467	      });
468	
469	    return () => {
470	      cancelled = true;
471	      resizeObserver?.disconnect();
472	      window.removeEventListener("resize", updateEmbedWidth);
473	      root.replaceChildren();
474	    };
475	  }, [embedHtml, shouldLoad]);
476	
477	  return (
478	    <div className="x-post-embed" data-x-status={status}>
479	      <div
480	        className={`x-post-native ${status === "ready" ? "is-ready" : ""}`}
481	        ref={nativeRef}
482	        aria-hidden={status !== "ready"}
483	      />
484	      {status !== "ready" && (
485	        <div className="x-post-fallback">
486	          {fallback}
487	          {!shouldLoad && (
488	            <button
489	              type="button"
490	              className="overlay-action-secondary x-post-load"
491	              onClick={() => setShouldLoad(true)}
492	            >
493	              Load post from X
494	            </button>
495	          )}
496	        </div>
497	      )}
498	    </div>
499	  );
500	}
