afterEach(async () => {
  for (const ai of processors.splice(0)) await ai.close();
  for (const library of libraries.splice(0)) library.db.close();
  Bun.gc(true);
});

afterAll(() => {
  Bun.gc(true);
  for (const root of roots.splice(0)) rmSync(root, { recursive: true, force: true });
});

const framePng = sharp({
  create: { width: 640, height: 360, channels: 3, background: "#335577" },
})
  .png()
  .toBuffer();

const models = {
  ocr: { recognize: async () => "" },
  embeddings: {
    embedText: async () => ({ model: TEXT_MODEL, vector: new Float32Array(2), bytes: Buffer.alloc(8) }),
    embedQuery: async () => ({ model: TEXT_MODEL, vector: new Float32Array(2), bytes: Buffer.alloc(8) }),
    embedImage: async () => ({ model: IMAGE_MODEL, vector: new Float32Array(2), bytes: Buffer.alloc(8) }),
  },
};

// Stands in for Electron's nativeImage; `thumbnail` decides what the shell returns.
function stubNativeImage(thumbnail: () => Promise<{ isEmpty(): boolean; toPNG(): Buffer }>) {
  const requested: { path: string; size: { width: number; height: number } }[] = [];
  return {
    requested,
    nativeImage: {
      createThumbnailFromPath: async (path: string, size: { width: number; height: number }) => {
        requested.push({ path, size });
        return thumbnail();
      },
    },
  };
}

const shellFrame = async () => ({ isEmpty: () => false, toPNG: () => Buffer.from(frameBytes) });
let frameBytes: Buffer;

function setup(nativeImage: Parameters<typeof createAiJobProcessors>[0]["nativeImage"]) {
  const root = mkdtempSync(join(tmpdir(), "inkling-video-poster-"));
  roots.push(root);
  const events: string[] = [];
  const library = openLibraryStorage(join(root, "library.sqlite3"), {
    createThumbnail: createImageThumbnail,
    jobQueue: { onUpdated: (id: string) => events.push(id) },
  });
  libraries.push(library);
  const ai = createAiJobProcessors({
    modelCacheDirectory: join(root, "models"),
    ...models,
    nativeImage,
  });
  processors.push(ai);
  // Only the poster kind is claimed, so a pump never waits on model jobs.
  const worker = new JobWorker(library, {
    processors: { [VIDEO_POSTER_JOB]: ai.processors[VIDEO_POSTER_JOB] },
    onIdle: ai.onIdle,
  });
  return { root, events, library, worker };
}

const saveVideo = (library: ReturnType<typeof openLibraryStorage>, fileName: string) =>
  library.saveFile({
    fileName,
    mimeType: "video/mp4",
    kind: "video",
    bytes: [0, 0, 0, 24, 102, 116, 121, 112],
  });

const jobRows = (library: ReturnType<typeof openLibraryStorage>) =>
  library.db.prepare("SELECT item_id, status, retry_count FROM jobs WHERE kind = ?").all(VIDEO_POSTER_JOB);

test("a captured video gets its poster from a background job, not from capture", async () => {
  frameBytes = await framePng;
  const shell = stubNativeImage(shellFrame);
  const { root, events, library, worker } = setup(shell.nativeImage);

  const video = await saveVideo(library, "clip.mp4");
  expect(shell.requested).toEqual([]);
  expect(library.getItem(video.id)?.thumbnailPath).toBeNull();
  expect(jobRows(library)).toEqual([{ item_id: video.id, status: "pending", retry_count: 0 }]);
  events.length = 0;

  await worker.pump();

  const posterPath = `assets/items/${video.id}/thumbnail.webp`;
  expect(library.getItem(video.id)?.thumbnailPath).toBe(posterPath);
  expect(shell.requested).toHaveLength(1);
  expect(shell.requested[0].path).toBe(
    realpathSync(join(root, "assets", "items", video.id, "clip.mp4")),
  );
  expect(shell.requested[0].size.width).toBe(512);
  expect(await sharp(join(root, posterPath.replace(/^assets\//u, "assets/"))).metadata()).toMatchObject({
    format: "webp",
    width: 512,
  });
