  expect(jobRows(library)).toEqual([{ item_id: video.id, status: "completed", retry_count: 0 }]);
});

const failures = [
  ["the shell returns an empty image", () => stubNativeImage(async () => ({ isEmpty: () => true, toPNG: () => Buffer.alloc(0) })), 4],
  [
    "the shell cannot read the file",
    () =>
      stubNativeImage(async () => {
        throw new Error("no thumbnail handler");
      }),
